INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Testen Integrationstests nur einzelne Funktionen?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Zusammenspiel"}, {"text": "Ja", "correct": false, "because": "Unit-Tests tun das"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Integrationstests?', 3, '[{"text": "Schnittstellen prüfen", "correct": true, "because": "Testet Interaktion"}, {"text": "Einzelne Logik validieren", "correct": false, "because": "Für Unit-Tests"}, {"text": "UI gestalten", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zu Integrationstests?', 5, '[{"text": "Schnittstellen", "correct": true, "because": "Prüft Verbindungen"}, {"text": "Zusammenspiel", "correct": true, "because": "Testet Komponenten"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Integrationstests prüfen Abhängigkeiten. b) Sie ersetzen Unit-Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Ergänzen Unit-Tests"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Integrationstests?', 4, '[{"text": "Komponenteninteraktion", "correct": false, "because": "Kern des Tests"}, {"text": "Schnittstellenverhalten", "correct": false, "because": "Wird geprüft"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Integrationstests immer manuell sind?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierbar"}, {"text": "Ja", "correct": false, "because": "Tools verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für Integrationstests?', 3, '[{"text": "Postman", "correct": true, "because": "Testet API-Schnittstellen"}, {"text": "Photoshop", "correct": false, "because": "Grafikdesign"}, {"text": "Notepad", "correct": false, "because": "Nur Text"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Integrationstests?', 5, '[{"text": "Systemstabilität", "correct": true, "because": "Prüft Zusammenarbeit"}, {"text": "Fehlerlokalisierung", "correct": true, "because": "Zeigt Schnittstellenprobleme"}, {"text": "Schnellere Builds", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Integrationstests sind komplexer als Unit-Tests. b) Sie testen nur Endpunkte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Testet Zusammenspiel"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Integrationstests?', 4, '[{"text": "Testumgebung", "correct": false, "because": "Simuliert System"}, {"text": "Schnittstellendefinition", "correct": false, "because": "Definiert Interaktion"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Testen Integrationstests auch Datenbanken?', 2, '[{"text": "Ja", "correct": true, "because": "Wenn Teil des Systems"}, {"text": "Nein", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte mache ich bei Integrationstests?', 4, '[{"text": "Komponenten verbinden", "correct": true, "because": "Simuliert System"}, {"text": "Interaktion prüfen", "correct": true, "because": "Validiert Zusammenspiel"}, {"text": "Farben anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Integrationstests Unit-Tests überflüssig machen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Ergänzen sich"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Ziele"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Integrationstests?', 3, '[{"text": "Schnittstellenkorrektheit", "correct": true, "because": "Sichert Funktion"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Integrationstests finden Systemfehler. b) Sie sind schneller als Unit-Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Oft langsamer"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei Integrationstests?', 5, '[{"text": "Komplexität", "correct": true, "because": "Viele Komponenten"}, {"text": "Abhängigkeiten", "correct": true, "because": "Externe Systeme"}, {"text": "Schnellere Tests", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Integrationstests unwichtig?', 3, '[{"text": "Komponentenverbindung", "correct": false, "because": "Kern des Tests"}, {"text": "Testdaten", "correct": false, "because": "Simuliert Nutzung"}, {"text": "Serverdesign", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Integrationstests immer automatisiert?', 3, '[{"text": "Nein", "correct": true, "because": "Können manuell sein"}, {"text": "Ja", "correct": false, "because": "Flexibel umsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Integrationstests vor Unit-Tests laufen?', 2, '[{"text": "Nein", "correct": true, "because": "Unit-Tests zuerst"}, {"text": "Ja", "correct": false, "because": "Nach Unit-Tests üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Schnittstellen zu testen?', 4, '[{"text": "API-Calls simulieren", "correct": true, "because": "Prüft Interaktion"}, {"text": "Code kompilieren", "correct": false, "because": "Kein Test"}, {"text": "UI rendern", "correct": false, "because": "Anderer Fokus"}]');
